@push('scripts')<script>
let idx=0,cart=new Map();const picker=document.querySelector('#product-picker'),body=document.querySelector('#cart');const selectedChannel=()=>document.querySelector('input[name="channel"]:checked').value;
function money(n){return'Rs. '+Number(n).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})}
function totals(){let subtotal=0;body.querySelectorAll('tr[data-id]').forEach(row=>{const line=Number(row.querySelector('.qty').value)*Number(row.querySelector('.price').value);subtotal+=line;row.querySelector('.line').textContent=money(line)});const grand=Math.max(0,subtotal-Number(document.querySelector('#discount').value||0));document.querySelector('#subtotal').textContent=money(subtotal);document.querySelector('#grand').textContent=money(grand);if(document.querySelector('#sale-type').value==='cash')document.querySelector('#paid').value=grand.toFixed(2)}
function updateChannel(){const channel=selectedChannel();cart.forEach(row=>row.querySelector('.price').value=channel==='retail'?row.dataset.retail:row.dataset.wholesale);totals()}
function add(option){if(cart.has(option.value)){const quantity=cart.get(option.value).querySelector('.qty');quantity.value=Number(quantity.value)+1;totals();return}document.querySelector('#empty')?.remove();const row=document.createElement('tr');row.dataset.id=option.value;row.dataset.retail=option.dataset.retail;row.dataset.wholesale=option.dataset.wholesale;row.innerHTML=`<td class="ps-3"><strong>${option.dataset.name}</strong><div class="small text-muted">${option.dataset.code} · Available ${option.dataset.stock}</div><input type="hidden" name="items[${idx}][product_id]" value="${option.value}"></td><td><input class="form-control qty" name="items[${idx}][quantity]" type="number" min=".0001" max="${option.dataset.stock}" step=".0001" value="1"></td><td><input class="form-control price" name="items[${idx}][unit_price]" type="number" min="0" step=".01" value="${selectedChannel()==='retail'?option.dataset.retail:option.dataset.wholesale}"></td><td class="line"></td><td><button class="btn btn-light remove" type="button">×</button></td>`;row.querySelectorAll('input').forEach(input=>input.oninput=totals);row.querySelector('.remove').onclick=()=>{cart.delete(option.value);row.remove();totals()};body.append(row);cart.set(option.value,row);idx++;totals()}
function updatePaymentTerms(){const credit=document.querySelector('#sale-type').value==='credit',customer=document.querySelector('#customer'),walkIn=[...customer.options].find(option=>option.dataset.walkIn==='1');document.querySelector('#due-wrap').classList.toggle('d-none',!credit);document.querySelector('#payment-fields').classList.toggle('d-none',credit);document.querySelector('#credit-note').classList.toggle('d-none',!credit);document.querySelector('#credit-customer-help').classList.toggle('d-none',!credit);if(walkIn)walkIn.disabled=credit;if(credit&&customer.selectedOptions[0]?.dataset.walkIn==='1'){const registered=[...customer.options].find(option=>option.dataset.walkIn!=='1');if(registered){customer.value=registered.value;customer.dispatchEvent(new Event('change'))}else customer.value=''}if(credit)document.querySelector('#paid').value='0';totals()}
picker.onchange=()=>{if(picker.value)add(picker.selectedOptions[0]);picker.value=''};document.querySelectorAll('input[name="channel"]').forEach(input=>input.onchange=updateChannel);document.querySelector('#customer').onchange=event=>{const desired=event.target.selectedOptions[0].dataset.channel;document.querySelector('#channel-'+desired).checked=true;updateChannel()};document.querySelector('#discount').oninput=totals;document.querySelector('#sale-type').onchange=updatePaymentTerms;document.querySelector('#method').onchange=event=>document.querySelector('#cheque').classList.toggle('d-none',event.target.value!=='cheque');document.querySelectorAll('#product-picker option[data-stock]').forEach(option=>{if(Number(option.dataset.stock)<=0){option.disabled=true;option.textContent=option.textContent.replace(/Stock\s+[\d.]+$/,'OUT OF STOCK')}});updatePaymentTerms();
</script>@endpush
